mapper.select:
SELECT FROM tb_users WHERE 1 = 1
AND status = #{criteria.status}
ORDER BY
updated_at name email status created_at
ASC DESC , id ASC LIMIT #{criteria.limit} OFFSET #{criteria.offset}

mapper.update:
UPDATE tb_users
   SET status = #{status},
       withdrawn_at = #{withdrawnAt, jdbcType=TIMESTAMP_WITH_TIMEZONE},
       updated_at = #{updatedAt}
 WHERE id = #{id}

mapper.select:
SELECT auth_invalidated_at
  FROM tb_users
 WHERE id = #{id}

mapper.update:
UPDATE tb_users
   SET auth_invalidated_at = GREATEST(COALESCE(auth_invalidated_at, #{at}), #{at}),
       updated_at = #{at}
 WHERE id = #{id}
